import { EventEmitter } from '../mochievents/index.js';
import { Socket, connect as netConnect } from '../mochinet/index.js';

function unsupported(name) {
    const err = new Error(`mochitls: ${name} is unavailable on MochiBerry runtime`);
    err.code = 'MOCHI_UNSUPPORTED';
    return err;
}

export class TLSSocket extends Socket {
    constructor() { super(); this.encrypted = true; }
}

export function connect() { const s = new TLSSocket(); queueMicrotask(() => s.emit('error', unsupported('tls.connect'))); return s; }
export function createServer() { throw unsupported('tls.createServer'); }
export const DEFAULT_MIN_VERSION = 'TLSv1.2';
export const DEFAULT_MAX_VERSION = 'TLSv1.3';
export default { TLSSocket, connect, createServer, DEFAULT_MIN_VERSION, DEFAULT_MAX_VERSION, Socket, netConnect };
